<script setup lang="ts">import{ref,onMounted,watch}from 'vue';import{lab,load}from '../stores/research';import{canEdit,isAdmin}from '../stores/auth';import*as surveys from '../api/surveys';import*as moorings from '../api/moorings';import*as bearings from '../api/bearings';import{useTask}from '../hooks/useTask';import type{Bearing}from '../types/domain';import{fmt}from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const{error,execute}=useTask(),survey=ref(0),mooring=ref(0),offset=ref(0),total=ref(0),rows=ref<Bearing[]>([]),description=ref(''),showCreate=ref(false),code=ref('new-survey'),name=ref('新增独立时段调查'),period=ref('2026-11-12'),json=ref('[{"code":"NEW-A-001","bearing":359,"observed_at":"2026-11-12T09:00"}]'),notice=ref('');async function read(){if(!survey.value)return;const r=await bearings.list(survey.value,mooring.value,offset.value);rows.value=r.rows;total.value=r.total;description.value=lab.surveys.find(s=>s.id===survey.value)?.description||'';}onMounted(()=>execute(async()=>{await load();survey.value=lab.surveys[0]?.id||0;mooring.value=lab.moorings[0]?.id||0;await read()}));watch([survey,mooring],()=>{offset.value=0;execute(read)});function save(){execute(async()=>{await surveys.patch(survey.value,{description:description.value});await load();notice.value='调查备注已保存';})}function create(){execute(async()=>{const s=await surveys.create({code:code.value,name:name.value,period:period.value,description:'新采集独立角度，需核对采样协议。'});await load();survey.value=s.id;showCreate.value=false;await read()})}function importRows(){execute(async()=>{const readings=JSON.parse(json.value);const r=await bearings.importRows({survey_id:survey.value,mooring_id:mooring.value,readings});notice.value='已导入'+r.inserted+'条；历史研究输入快照不改变';await read()})}function editMooring(id:number,current:string){execute(async()=>{await moorings.patch(id,{description:current});await load();notice.value='浮标说明已保存'})}</script><template><PageHeading index="02" title="把角度，连同采样协议一起保存。" text="0°北、顺时针；每期每浮标最多250条。研究使用输入快照，新增采样不会改写历史结果。"><button v-if="canEdit" class="outline" @click="showCreate=!showCreate">新建调查 +</button></PageHeading><ErrorNotice :message="error" @retry="execute(read)"/><p v-if="notice" class="success" role="status">{{notice}}</p><form v-if="showCreate" class="inline-form" @submit.prevent="create"><label>调查编号<input v-model="code" required pattern="[a-z0-9-]+"></label><label>调查名称<input v-model="name" required></label><label>时段<input v-model="period" required></label><button class="primary">保存新调查</button></form><div class="filters"><label>调查期<select v-model="survey"><option v-for="s in lab.surveys" :value="s.id">{{s.name}}</option></select></label><label>浮标<select v-model="mooring"><option v-for="m in lab.moorings" :value="m.id">{{m.name}}</option></select></label></div><div class="sources-grid"><section><div class="table-wrap"><table><thead><tr><th>采样编号</th><th>采样时刻</th><th>方向 / °</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.code}}</td><td>{{r.observed_at}}</td><td class="numeric">{{fmt(r.bearing,4)}}</td></tr></tbody></table></div><p v-if="!rows.length" class="empty">当前组尚无采样。导入独立角度后再建立研究。</p><div class="pagination"><span>共{{total}}条 / {{offset+1}}–{{Math.min(total,offset+24)}}</span><button class="outline" :disabled="offset===0" @click="offset-=24;execute(read)">前24条</button><button class="outline" :disabled="offset+24>=total" @click="offset+=24;execute(read)">后24条</button></div></section><aside class="source-margin"><h2>调查备忘</h2><label>采样说明<textarea v-model="description" :readonly="!canEdit" rows="5"/></label><button v-if="canEdit" class="outline" @click="save">保存调查备注</button><details v-if="canEdit"><summary>导入角度JSON</summary><p>code自然键唯一，bearing必须0≤角度&lt;360；不把未知角度转成0。</p><label>采样JSON<textarea v-model="json" rows="7"/></label><button class="primary" @click="importRows">校验并导入</button></details><div v-for="m in lab.moorings" class="mooring-note"><p class="eyebrow">{{m.code}}</p><h3>{{m.name}}</h3><label>浮标说明<textarea v-model="m.description" :readonly="!isAdmin" rows="3"/></label><button v-if="isAdmin" class="text-button" @click="editMooring(m.id,m.description)">保存浮标说明 ↗</button></div></aside></div></template>
